package org.freecad.mobilelab;
import android.app.*;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import org.json.*;
import java.util.*;

/** Touch node canvas with typed ports and editable number sliders. */
final class GraphEditor {
    interface Result{void accept(String json);}
    static void show(Activity activity,String initial,Result result){new Editor(activity,initial,result).show();}
    private static final class Editor {
        final Activity a;final Result result;JSONObject graph;JSONArray nodes;int selected=0;Dialog dialog;CanvasView canvas;TextView status;boolean live;final android.os.Handler debounce=new android.os.Handler(android.os.Looper.getMainLooper());final Runnable applyLive;
        Editor(Activity a,String initial,Result result){this.a=a;this.result=result;this.applyLive=()->{try{if(live&&dialog.isShowing()){ParametricGraph.validate(graph.toString());result.accept(graph.toString());}}catch(Exception e){L10n.setText(status,"Preview waiting: "+e.getMessage());}};try{graph=new JSONObject(initial==null?ParametricGraph.example():initial);nodes=graph.getJSONArray("nodes");}catch(Exception e){throw new IllegalArgumentException("Cannot read graph",e);}}
        int dp(int x){return Math.round(x*a.getResources().getDisplayMetrics().density);}
        void show(){dialog=new Dialog(a);LinearLayout root=new LinearLayout(a);root.setOrientation(1);root.setPadding(dp(10),dp(10),dp(10),dp(10));root.setBackgroundColor(0xff111820);status=new TextView(a);status.setTextColor(0xffedf3f8);L10n.setText(status,"Parametric graph · tap a node, then Edit / connect.\nTyped point/list/geometry ports. Number values update on Evaluate.");root.addView(status);CheckBox toggle=new CheckBox(a);L10n.setText(toggle,"Live apply after 450 ms · creates Undo checkpoints");toggle.setTextColor(0xffedf3f8);toggle.setOnCheckedChangeListener((b,on)->{live=on;debounce.removeCallbacks(applyLive);if(on)debounce.postDelayed(applyLive,450);});root.addView(toggle);ScrollView scroll=new ScrollView(a);canvas=new CanvasView();scroll.addView(canvas,new ScrollView.LayoutParams(-1,dp(Math.max(500,((nodes.length()+1)/2)*150))));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bar=new LinearLayout(a);for(String title:new String[]{"Add","Edit / connect","Delete","Evaluate"}){Button b=new Button(a);L10n.setText(b,title);b.setTextSize(11);bar.addView(b,new LinearLayout.LayoutParams(0,dp(54),1));b.setOnClickListener(v->{if(title.equals("Add"))add();if(title.startsWith("Edit"))edit();if(title.equals("Delete"))delete();if(title.equals("Evaluate"))evaluate();});}root.addView(bar);Button close=new Button(a);L10n.setText(close,"Close");close.setOnClickListener(v->dialog.dismiss());root.addView(close);dialog.setOnDismissListener(d->debounce.removeCallbacks(applyLive));dialog.setContentView(root);dialog.show();dialog.getWindow().setLayout(-1,-1);}
        void refresh(){canvas.getLayoutParams().height=dp(Math.max(500,((nodes.length()+1)/2)*150));canvas.requestLayout();canvas.invalidate();}
        void error(Exception e){new UiDialog(a).setTitle("Node graph").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}
        void add(){new UiDialog(a).setTitle("Add component").setItems(L10n.labels(a,ParametricGraph.KINDS),(d,w)->{try{if(nodes.length()>=80)throw new IllegalArgumentException("Maximum 80 components");int id=1;for(int i=0;i<nodes.length();i++)id=Math.max(id,nodes.getJSONObject(i).getInt("id")+1);String kind=ParametricGraph.KINDS[w];JSONObject n=new JSONObject().put("id",id).put("kind",kind).put("value",1);JSONArray inputs=new JSONArray();for(String ignored:ParametricGraph.ports(kind))inputs.put(0);n.put("inputs",inputs);nodes.put(n);selected=nodes.length()-1;refresh();edit();}catch(Exception e){error(e);}}).show();}
        void edit(){try{if(nodes.length()==0)return;JSONObject n=nodes.getJSONObject(selected);String kind=n.getString("kind");LinearLayout panel=new LinearLayout(a);panel.setOrientation(1);panel.setPadding(dp(16),dp(8),dp(16),0);EditText number=new EditText(a);ArrayList<Spinner> ports=new ArrayList<>();ArrayList<int[]> candidates=new ArrayList<>();
            if(kind.equals("Number")){number.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);number.setText(String.valueOf(n.optDouble("value",1)));panel.addView(number);SeekBar slider=new SeekBar(a);double initial=n.optDouble("value",1),range=Math.max(20,Math.abs(initial)*4);slider.setMax(1000);slider.setProgress((int)Math.max(0,Math.min(1000,(initial/range+.5)*1000)));slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int value,boolean user){if(user){double x=(value/1000.-.5)*range;number.setText(String.format(java.util.Locale.US,L10n.text(a,"%.4f"),x));if(live)try{n.put("value",x);debounce.removeCallbacks(applyLive);debounce.postDelayed(applyLive,450);}catch(Exception e){L10n.setText(status,e.getMessage());}}}});panel.addView(slider);}
            String[] labels=ParametricGraph.ports(kind);for(int p=0;p<labels.length;p++){TextView label=new TextView(a);L10n.setText(label,labels[p]);panel.addView(label);ArrayList<String> names=new ArrayList<>();ArrayList<Integer> ids=new ArrayList<>();names.add(L10n.text(a,"Choose input"));ids.add(0);for(int i=0;i<nodes.length();i++){JSONObject candidate=nodes.getJSONObject(i);if(i!=selected&&ParametricGraph.compatible(kind,p,candidate.getString("kind"))){names.add(L10n.text(a,candidate.getString("kind"))+" "+candidate.getInt("id"));ids.add(candidate.getInt("id"));}}Spinner spin=new Spinner(a);spin.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,names));int previous=n.getJSONArray("inputs").optInt(p);for(int i=0;i<ids.size();i++)if(ids.get(i)==previous)spin.setSelection(i);panel.addView(spin);ports.add(spin);int[] keys=new int[ids.size()];for(int i=0;i<keys.length;i++)keys[i]=ids.get(i);candidates.add(keys);}
            EditText group=new EditText(a);L10n.setHint(group,"Group label (optional)");group.setText(n.optString("group"));group.setSingleLine(true);panel.addView(group);CheckBox output=new CheckBox(a);L10n.setText(output,"Show as graph output");output.setEnabled(ParametricGraph.outputType(kind).equals("geometry"));JSONArray outs=graph.optJSONArray("outputs");for(int i=0;outs!=null&&i<outs.length();i++)if(outs.optInt(i)==n.getInt("id"))output.setChecked(true);panel.addView(output);ScrollView scroll=new ScrollView(a);scroll.addView(panel);AlertDialog form=new UiDialog(a).setTitle(kind+" "+n.getInt("id")).setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();form.setOnShowListener(v->form.getButton(-1).setOnClickListener(b->{try{if(kind.equals("Number")){double value=Double.parseDouble(number.getText().toString().replace(',','.'));if(!Double.isFinite(value))throw new IllegalArgumentException("Enter a finite number");n.put("value",value);}if(group.getText().length()>80)throw new IllegalArgumentException("Group label exceeds 80 characters");n.put("group",group.getText().toString());JSONArray connected=new JSONArray();for(int i=0;i<ports.size();i++)connected.put(candidates.get(i)[ports.get(i).getSelectedItemPosition()]);n.put("inputs",connected);JSONArray newOutputs=new JSONArray();for(int i=0;outs!=null&&i<outs.length();i++)if(outs.getInt(i)!=n.getInt("id"))newOutputs.put(outs.getInt(i));if(output.isChecked())newOutputs.put(n.getInt("id"));graph.put("outputs",newOutputs);form.dismiss();refresh();if(live){debounce.removeCallbacks(applyLive);debounce.postDelayed(applyLive,450);}}catch(Exception e){error(e);}}));form.show();
        }catch(Exception e){error(e);}}
        void delete(){try{if(nodes.length()==0)return;int removed=nodes.getJSONObject(selected).getInt("id");nodes.remove(selected);selected=Math.max(0,selected-1);JSONArray outs=graph.optJSONArray("outputs"),next=new JSONArray();for(int i=0;outs!=null&&i<outs.length();i++)if(outs.getInt(i)!=removed)next.put(outs.getInt(i));graph.put("outputs",next);refresh();}catch(Exception e){error(e);}}
        void evaluate(){try{ParametricGraph.validate(graph.toString());dialog.dismiss();result.accept(graph.toString());}catch(Exception e){error(e);}}
        final class CanvasView extends View {
            final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);CanvasView(){super(a);}
            RectF rect(int i){float col=getWidth()/2f,x=(i%2)*col+dp(8),y=(i/2)*dp(150)+dp(12);return new RectF(x,y,x+col-dp(16),y+dp(118));}
            @Override protected void onDraw(Canvas c){super.onDraw(c);p.setColor(0xff23303d);p.setStrokeWidth(1);for(int x=0;x<getWidth();x+=dp(24))c.drawLine(x,0,x,getHeight(),p);for(int y=0;y<getHeight();y+=dp(24))c.drawLine(0,y,getWidth(),y,p);try{Map<Integer,Integer> ids=new HashMap<>();for(int i=0;i<nodes.length();i++)ids.put(nodes.getJSONObject(i).getInt("id"),i);p.setColor(0xff59dfc4);p.setStrokeWidth(dp(2));for(int i=0;i<nodes.length();i++){JSONArray inputs=nodes.getJSONObject(i).getJSONArray("inputs");for(int j=0;j<inputs.length();j++){Integer source=ids.get(inputs.getInt(j));if(source!=null){RectF r=rect(source),to=rect(i);c.drawLine(r.centerX(),r.bottom,to.centerX(),to.top,p);}}}for(int i=0;i<nodes.length();i++){JSONObject node=nodes.getJSONObject(i);RectF r=rect(i);p.setColor(i==selected?0xff32534f:0xff1b2633);c.drawRoundRect(r,dp(10),dp(10),p);p.setColor(0xffedf3f8);p.setTextSize(dp(13));c.drawText(L10n.text(a,node.getString("kind"))+" "+node.getInt("id"),r.left+dp(10),r.top+dp(25),p);p.setColor(0xff99aabe);p.setTextSize(dp(11));c.drawText(node.getString("kind").equals("Number")?String.format(java.util.Locale.US,L10n.text(a,"Value: %.4f"),node.optDouble("value")):"Inputs: "+node.getJSONArray("inputs"),r.left+dp(10),r.top+dp(50),p);c.drawText(node.optString("group").isEmpty()?"Tap → Edit / connect":node.optString("group"),r.left+dp(10),r.top+dp(88),p);}}catch(Exception e){L10n.setText(status,e.getMessage());}}
            @Override public boolean onTouchEvent(MotionEvent event){if(event.getAction()==MotionEvent.ACTION_UP){for(int i=0;i<nodes.length();i++)if(rect(i).contains(event.getX(),event.getY())){selected=i;invalidate();return true;}}return true;}
        }
    }
}
